static av_cold int get_local_pos(SwsContext *s, int chr_subsample, int pos, int dir)
{
    if (pos == -1 || pos <= -513) {
        pos = (128 << chr_subsample) - 128;
    }
    pos += 128; // relative to ideal left edge
    return pos >> chr_subsample;
}

typedef struct {
    int flag;                   ///< flag associated to the algorithm
    const char *description;    ///< human-readable description
    int size_factor;            ///< size factor used when initing the filters
} ScaleAlgorithm;

static const ScaleAlgorithm scale_algorithms[] = {
    { SWS_AREA,          "area averaging",                  1 /* downscale only, for upscale it is bilinear */ },
    { SWS_BICUBIC,       "bicubic",                         4 },
    { SWS_BICUBLIN,      "luma bicubic / chroma bilinear", -1 },
    { SWS_BILINEAR,      "bilinear",                        2 },
    { SWS_FAST_BILINEAR, "fast bilinear",                  -1 },
    { SWS_GAUSS,         "Gaussian",                        8 /* infinite ;) */ },
    { SWS_LANCZOS,       "Lanczos",                        -1 /* custom */ },
    { SWS_POINT,         "nearest neighbor / point",       -1 },
    { SWS_SINC,          "sinc",                           20 /* infinite ;) */ },
    { SWS_SPLINE,        "bicubic spline",                 20 /* infinite :)*/ },
    { SWS_X,             "experimental",                    8 },
};

static av_cold int initFilter(int16_t **outFilter, int32_t **filterPos,
                              int *outFilterSize, int xInc, int srcW,
                              int dstW, int filterAlign, int one,

            double floatd;
            int64_t coeff;

            if (xInc > 1 << 16)
                d = d * dstW / srcW;
            floatd = d * (1.0 / (1 << 30));

            if (flags & SWS_BICUBIC) {
                int64_t B = (param[0] != SWS_PARAM_DEFAULT ? param[0] :   0) * (1 << 24);
                int64_t C = (param[1] != SWS_PARAM_DEFAULT ? param[1] : 0.6) * (1 << 24);

                if (d >= 1LL << 31) {
                    coeff = 0.0;
                } else {
                    int64_t dd  = (d  * d) >> 30;
                    int64_t ddd = (dd * d) >> 30;

                    if (d < 1LL << 30)
                        coeff =  (12 * (1 << 24) -  9 * B - 6 * C) * ddd +
                                (-18 * (1 << 24) + 12 * B + 6 * C) *  dd +
                                  (6 * (1 << 24) -  2 * B)         * (1 << 30);
                    else
                        coeff =      (-B -  6 * C) * ddd +
                                  (6 * B + 30 * C) * dd  +
                                (-12 * B - 48 * C) * d   +
                                  (8 * B + 24 * C) * (1 << 30);
                }
                coeff /= (1LL<<54)/fone;
            } else if (flags & SWS_X) {
                double A = param[0] != SWS_PARAM_DEFAULT ? param[0] : 1.0;
                double c;

                if (floatd < 1.0)
                    c = cos(floatd * M_PI);
                else
                    c = -1.0;
                if (c < 0.0)
                    c = -pow(-c, A);
                else
                    c = pow(c, A);
                coeff = (c * 0.5 + 0.5) * fone;
            } else if (flags & SWS_AREA) {
                int64_t d2 = d - (1 << 29);
                if (d2 * xInc < -(1LL << (29 + 16)))
                    coeff = 1.0 * (1LL << (30 + 16));
                else if (d2 * xInc < (1LL << (29 + 16)))
                    coeff = -d2 * xInc + (1LL << (29 + 16));
                else
                    coeff = 0.0;
                coeff *= fone >> (30 + 16);
            } else if (flags & SWS_GAUSS) {
                double p = param[0] != SWS_PARAM_DEFAULT ? param[0] : 3.0;
                coeff = exp2(-p * floatd * floatd) * fone;
            } else if (flags & SWS_SINC) {
                coeff = (d ? sin(floatd * M_PI) / (floatd * M_PI) : 1.0) * fone;
            } else if (flags & SWS_LANCZOS) {
                double p = param[0] != SWS_PARAM_DEFAULT ? param[0] : 3.0;
                coeff = (d ? sin(floatd * M_PI) * sin(floatd * M_PI / p) /
                         (floatd * floatd * M_PI * M_PI / p) : 1.0) * fone;
                if (floatd > p)
                    coeff = 0;
            } else if (flags & SWS_BILINEAR) {
                coeff = (1 << 30) - d;
                if (coeff < 0)
                    coeff = 0;
                coeff *= fone >> 30;
            } else if (flags & SWS_SPLINE) {
                double p = -2.196152422706632;
                coeff = getSplineCoeff(1.0, 0.0, p, -p - 1.0, floatd) * fone;
            } else {
                av_assert0(0);
            }

            filter[i * filterSize + j] = coeff;
            xx++;
        }
        xDstInSrc += 2LL * xInc;
    }
